    expect(observed.usage()).toEqual(usage);
  });

  it('sums usage reported by each provider round', async () => {
    const observed = observeUsage();
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 11, outputTokens: 3, totalTokens: 14}}],
